import Database from 'better-sqlite3'
import path from 'path'

const DB_PATH = path.join(process.cwd(), 'blog.db')

let _db: Database.Database | null = null

export function getDb(): Database.Database {
  if (!_db) {
    _db = new Database(DB_PATH)
    _db.pragma('journal_mode = WAL')
  }
  return _db
}

export interface Post {
  id: number
  title: string
  content: string
}

export function initDb() {
  const db = getDb()
  db.exec(`
    CREATE TABLE IF NOT EXISTS posts (
      id INTEGER PRIMARY KEY,
      title TEXT NOT NULL,
      content TEXT NOT NULL
    )
  `)
}

import { createServerFn } from '@tanstack/react-start'
import { getDb, type Post } from './db'
import { marked } from 'marked'

export const getPosts = createServerFn({ method: 'GET' }).handler(
  async (): Promise<Post[]> => {
    const db = getDb()
    const posts = db.prepare('SELECT id, title, content FROM posts ORDER BY id').all() as Post[]
    return posts
  },
)

export const getPost = createServerFn({ method: 'GET' })
  .validator((id: string) => id)
  .handler(
    async ({ data: id }): Promise<Post & { htmlContent: string }> => {
      const db = getDb()
      const post = db.prepare('SELECT id, title, content FROM posts WHERE id = ?').get(id) as Post | undefined
      if (!post) {
        throw new Error(`Post with id ${id} not found`)
      }
      const htmlContent = await marked(post.content)
      return { ...post, htmlContent }
    },
  )

import {
  createRouter,
  createRoute,
  createRootRoute,
  Outlet,
} from '@tanstack/react-router'
import { IndexRoute } from './routes/IndexRoute'
import { PostRoute } from './routes/posts/PostRoute'

const rootRoute = createRootRoute({
  component: () => (
    <div>
      <Outlet />
    </div>
  ),
})

const indexRoute = createRoute({
  getParentRoute: () => rootRoute,
  path: '/',
  ...IndexRoute,
})

const postRoute = createRoute({
  getParentRoute: () => rootRoute,
  path: '/posts/$postId',
  ...PostRoute,
})

const routeTree = rootRoute.addChildren([indexRoute, postRoute])

export const router = createRouter({ routeTree })

declare module '@tanstack/react-router' {
  interface Register {
    router: typeof router
  }
}

import { createServerFn } from '@tanstack/react-start'
import { getDb, type Post } from '../db'

const fetchPosts = createServerFn({ method: 'GET' }).handler(
  async (): Promise<Post[]> => {
    const db = getDb()
    const posts = db.prepare('SELECT id, title, content FROM posts ORDER BY id').all() as Post[]
    return posts
  },
)

export const IndexRoute = {
  loader: () => fetchPosts(),
  component: function IndexComponent() {
    const posts = IndexRoute.useLoaderData() as Post[]
    return (
      <div>
        <h1>Blog Posts</h1>
        <ul>
          {posts.map((post) => (
            <li key={post.id}>
              <a href={`/posts/${post.id}`}>{post.title}</a>
            </li>
          ))}
        </ul>
      </div>
    )
  },
}

